import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../../pages/hardware_wallet/hardware_reconnect_dialog.dart';
import '../../../../providers/global/prefs_provider.dart';
import '../../../../providers/hardware/hardware_wallet_provider.dart';
import '../../../../themes/stack_colors.dart';
import '../../../../utilities/text_styles.dart';
import '../../../../wallets/hardware/hardware_wallet_device_family.dart';
import '../../../../wallets/isar/models/wallet_info.dart';
import '../../../../wallets/isar/providers/wallet_info_provider.dart';

class HardwareDeviceStatusButton extends ConsumerStatefulWidget {
  const HardwareDeviceStatusButton({super.key, required this.walletId});

  final String walletId;

  @override
  ConsumerState<HardwareDeviceStatusButton> createState() =>
      _HardwareDeviceStatusButtonState();
}

class _HardwareDeviceStatusButtonState
    extends ConsumerState<HardwareDeviceStatusButton> {
  bool _isConnected = false;
  HardwareWalletDeviceFamily? _family;

  @override
  void initState() {
    super.initState();
    _updateConnectionState();
  }

  void _updateConnectionState() {
    final walletInfo = ref.read(pWalletInfo(widget.walletId));
    final familyStr =
        walletInfo.otherData[WalletInfoKeys.hardwareDeviceFamilyKey] as String?;
    if (familyStr != null) {
      _family = HardwareWalletDeviceFamily.values.byName(familyStr);
    }

    final prefs = ref.read(prefsChangeNotifierProvider);
    if (prefs.enableMockHardwareAutoSigner) {
      _isConnected = true;
      return;
    }

    if (_family != null) {
      final adapter = ref.read(hardwareAdapterProvider(_family!));
      _isConnected = adapter?.isConnected ?? false;
    }
  }

  Future<void> _onPressed() async {
    if (_family == null) return;

    await HardwareReconnectDialog.show(context, _family!);
    if (mounted) {
      setState(() {
        _updateConnectionState();
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    ref.watch(pWalletInfo(widget.walletId));
    _updateConnectionState();

    final color = _isConnected
        ? Theme.of(context).extension<StackColors>()!.accentColorGreen
        : Theme.of(context).extension<StackColors>()!.accentColorRed;

    final label = _isConnected ? "Device connected" : "Device disconnected";

    return RawMaterialButton(
      hoverColor: color.withOpacity(0.1),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(1000)),
      onPressed: _onPressed,
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 16, horizontal: 32),
        child: Row(
          children: [
            Icon(
              Icons.usb_rounded,
              size: 24,
              color: color,
            ),
            const SizedBox(width: 6),
            Text(
              label,
              style: STextStyles.desktopMenuItemSelected(
                context,
              ).copyWith(color: color),
            ),
          ],
        ),
      ),
    );
  }
}
